import { test, expect } from '@playwright/test';
import { supabaseSession, readAuditLog } from './audit-helpers';

test.use({ storageState: '../auth/dispatcher.json' });

test.describe('Audit log — RLS для не супер-админа (#fc4fa4)', () => {
  test('Admin-dispatcher reading AuditLog directly via REST gets 200 and an empty list #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    const s = await supabaseSession(page);
    const { status, body } = await readAuditLog(page, s);
    expect(status, 'GET /rest/v1/AuditLog').toBe(200);
    expect(body, 'журнал закрыт RLS для участника команды').toEqual([]);
  });
});
